def wrap_break_long_words(text, width):
    words = text.split()
    lines = []
    current = ''
    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ''
            while len(word) > width:
                lines.append(word[:width])
                word = word[width:]
        if not current:
            current = word
        else:
            candidate = current + ' ' + word
            if len(candidate) <= width:
                current = candidate
            else:
                lines.append(current)
                current = word
    if current:
        lines.append(current)
    return lines

def wrap_fixed_lines(text, width, max_lines):
    words = text.split()
    lines = []
    current = ''
    for word in words:
        if not current:
            current = word
        else:
            candidate = current + ' ' + word
            if len(candidate) <= width:
                current = candidate
            else:
                lines.append(current)
                current = word
    if current:
        lines.append(current)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        last = lines[-1]
        max_content_len = width - 3
        if max_content_len < 0:
            max_content_len = 0
        if len(last) > max_content_len:
            last = last[:max_content_len]
        lines[-1] = last + '...'
    return lines

def wrap_preserve_paragraphs(text, width):
    paragraphs = text.split('\n')
    all_lines = []
    for para in paragraphs:
        words = para.split()
        if not words:
            all_lines.append('')
            continue
        lines = []
        current = ''
        for word in words:
            if not current:
                current = word
            else:
                candidate = current + ' ' + word
                if len(candidate) <= width:
                    current = candidate
                else:
                    lines.append(current)
                    current = word
        if current:
            lines.append(current)
        all_lines.extend(lines)
    return '\n'.join(all_lines)

def wrap_count_lines(text, width):
    words = text.split()
    if not words:
        return 0
    lines = 0
    current = ''
    for word in words:
        if not current:
            current = word
        else:
            candidate = current + ' ' + word
            if len(candidate) <= width:
                current = candidate
            else:
                lines += 1
                current = word
    if current:
        lines += 1
    return lines

def dedent_lines(text, n):
    lines = text.split('\n')
    result = []
    for line in lines:
        count = 0
        while count < n and count < len(line) and line[count] == ' ':
            count += 1
        result.append(line[count:])
    return '\n'.join(result)

def indent_with_char(text, n, ch):
    lines = text.split('\n')
    prefix = ch * n
    return '\n'.join(prefix + line for line in lines)

def common_dedent(lines):
    def leading_spaces(s):
        count = 0
        for ch in s:
            if ch == ' ':
                count += 1
            else:
                break
        return count
    non_blank_indents = [leading_spaces(line) for line in lines if line.strip() != '']
    if not non_blank_indents:
        return list(lines)
    m = min(non_blank_indents)
    result = []
    for line in lines:
        if line.strip() == '':
            result.append(line)
        else:
            result.append(line[m:])
    return result

def indent_except_first(text, n):
    lines = text.split('\n')
    prefix = ' ' * n
    new_lines = [lines[0]] + [prefix + l for l in lines[1:]]
    return '\n'.join(new_lines)

def dedent_tabs(text):
    lines = text.split('\n')
    result = []
    for line in lines:
        if line.startswith('\t'):
            result.append('    ' + line[1:])
        else:
            result.append(line)
    return '\n'.join(result)

def indent_block(lines, n):
    prefix = ' ' * n
    return '\n'.join(prefix + line for line in lines)

def reindent(text, old_n, new_n):
    lines = text.split('\n')
    result = []
    for line in lines:
        count = 0
        while count < len(line) and line[count] == ' ':
            count += 1
        if count >= old_n:
            result.append(' ' * new_n + line[old_n:])
        else:
            result.append(line)
    return '\n'.join(result)

def render_checklist(items):
    lines = []
    for text, done in items:
        prefix = '[x] ' if done else '[ ] '
        lines.append(prefix + text)
    return '\n'.join(lines)

def render_lettered_list(items):
    lines = []
    for i, item in enumerate(items):
        letter = chr(ord('a') + i)
        lines.append(f'{letter}. {item}')
    return '\n'.join(lines)

def render_bullets_indented(items, bullet, indent):
    prefix = ' ' * indent
    return '\n'.join(prefix + bullet + ' ' + item for item in items)

def render_numbered_padded(items):
    n = len(items)
    if n == 0:
        return ''
    width = len(str(n))
    lines = []
    for i, item in enumerate(items):
        num = str(i + 1).zfill(width)
        lines.append(f'{num}. {item}')
    return '\n'.join(lines)

def mask_phone_all_but_last(digits, keep):
    length = len(digits)
    if keep >= length:
        return digits
    if keep <= 0:
        return '*' * length
    return '*' * (length - keep) + digits[length - keep:]
